"""Original small English corpus; relevance labels are human-authored, not model outputs."""
import json
from pathlib import Path
# Each topic supplies two relevant documents and a paraphrased query.
TOPICS = [
 ('recovery', 'Recovering deleted database records', 'Point in time recovery restores a full backup and then replays transaction logs up to the instant before an accidental deletion. Keep backups off the production disk and regularly test restoration.', 'Testing database backups', 'A backup is useful only when it can be restored. Rehearse recovery in an isolated database and check table counts, application reads, and the last committed transaction before switching traffic.', 'How can I restore records after accidentally deleting a database table?'),
 ('index', 'Choosing database indexes', 'An index helps the database locate matching rows without scanning every record. Composite indexes are useful for repeated filters on several columns. Extra indexes consume disk space and make writes more expensive.', 'Reading query execution plans', 'Use EXPLAIN to inspect whether a query scans a whole table or uses an index. Compare estimated and actual row counts. A predicate on an unindexed column often causes slow queries on large tables.', 'How do I avoid reading an entire large table for a filtered query?'),
 ('transaction', 'Atomic database transactions', 'A transaction groups multiple writes into one atomic operation. COMMIT publishes all changes; ROLLBACK cancels them. A transfer between bank accounts must debit and credit together so money cannot disappear.', 'Isolation under concurrent updates', 'Concurrent transactions can observe different snapshots depending on isolation level. Locks or optimistic version checks prevent lost updates. Retry serialization failures and keep transaction boundaries short.', 'How can a bank transfer update two balances together without losing money?'),
 ('vector', 'Semantic nearest neighbor search', 'Dense embeddings represent text meaning as numerical vectors. A nearest neighbor index finds similar vectors with cosine or Euclidean distance. Semantic retrieval can match a question even when wording differs from the document.', 'Approximate vector indexes', 'HNSW builds a graph for approximate nearest neighbor lookup. Search exploration trades speed for recall. Measure recall against exact neighbors on representative queries before selecting the search parameter.', 'How can a search engine find related ideas when the words are different?'),
 ('hybrid', 'Combining keyword and semantic retrieval', 'Hybrid search retrieves both lexical matches and semantic neighbors. Exact product codes benefit from full text search while paraphrased questions benefit from embeddings. A database can fuse both rankings in a single retrieval operation.', 'Reciprocal rank fusion', 'Reciprocal rank fusion combines positions from multiple ranked lists. Each result contributes one divided by a rank constant plus its position. The database returns the fused order; raw vector distances and keyword scores do not need the same scale.', 'How should exact product identifiers and paraphrased questions be searched together?'),
 ('quantization', 'Reducing embedding model size', 'Quantization represents model weights with fewer bits. INT8 often reduces a floating point model to about one quarter of its original weight storage. Compare recall and ranking quality before accepting the smaller model.', 'Half precision model evaluation', 'FP16 stores floating point weights with sixteen bits rather than thirty two. Hardware support affects execution speed. Use the same corpus and query labels to compare retrieval quality, memory use and loading time with FP32.', 'How can I shrink a local embedding model and check that search quality stays good?'),
 ('browser', 'WebGPU and browser inference', 'WebGPU lets a browser dispatch tensor operations to a local graphics processor. Request a GPU adapter explicitly and check its features. A browser can perform model inference without uploading document text to a cloud inference service.', 'WASM fallback in a browser', 'WebAssembly can run local inference when a graphics adapter is unavailable. Show the active backend in the interface, keep the same model contract, and exercise document ingestion and query embedding after automatic fallback.', 'How can local browser inference keep working on a machine without GPU support?'),
 ('batch', 'Batching embedding requests', 'Batch processing runs several documents through the embedding model at once. Padding and sequence lengths affect efficiency. Compare batch sizes on identical hardware and text, since larger batches can increase memory and sometimes reduce throughput.', 'Cold starts and warm measurements', 'The first inference includes shader compilation and memory allocation. Report cold startup separately from repeated warm requests. Preserve all raw measurements and report medians instead of selecting the fastest observation.', 'What is a fair way to compare batch embedding performance without hiding startup costs?'),
 ('incremental', 'Incremental knowledge base imports', 'Use deterministic document identifiers to upsert existing content and append new content. Refresh the vector index after a write batch, then verify the new documents can be retrieved. Do not mix embeddings from different models in one collection.', 'Keeping knowledge bases separate', 'Every import and query must use the selected collection. Switching between workspaces must not show results from an earlier workspace. Separate collections for incompatible model versions prevent meaningless vector comparisons.', 'How can repeated imports and switching knowledge bases avoid duplicate or stale search results?'),
 ('quality', 'Measuring retrieval recall', 'Recall at K is the number of relevant documents among the first K results divided by all relevant documents for the query. A labelled evaluation set makes quality comparisons repeatable. Include queries with several relevant passages.', 'Evaluating ranked search results', 'Normalized discounted cumulative gain rewards relevant documents near the top of a ranking. Compare observed discounted gain with the ideal ranking for the same relevance labels. Keep the query set fixed across model configurations.', 'Which metrics evaluate both finding relevant documents and putting them first?'),
 ('security', 'Safe handling of application secrets', 'Database passwords belong in environment configuration rather than browser JavaScript or a public repository. Bind development servers to loopback by default. Use a protected reverse proxy when exposing an application to other users.', 'Parameterizing SQL queries', 'Prepared statements bind values separately from SQL syntax. Validate identifiers against a fixed allowlist because table names usually cannot be parameter placeholders. Do not concatenate raw user input into executable SQL.', 'How do I prevent credentials from leaking to the browser and malicious SQL input?'),
 ('files', 'Reading CSV files reliably', 'CSV fields may contain quoted commas, escaped quotes or newline characters. A correct reader follows the quoting rules rather than splitting every line on commas. Preserve empty fields and detect encoding errors explicitly.', 'Streaming large data files', 'A streaming parser processes input in bounded chunks instead of loading the entire file into memory. Schema inference should account for later rows with wider types. Report malformed records without silently truncating the dataset.', 'How can large comma separated files be parsed without breaking quoted multiline fields?'),
]
DISTRACTORS = [
 ('garden', 'Watering a vegetable garden', 'Tomatoes grow best with consistent soil moisture, sufficient sunlight and support for heavy branches. Water the root zone early in the morning. Mulch reduces evaporation and suppresses weeds.'),
 ('bike', 'Bicycle maintenance', 'Check tire pressure and brake alignment before a long ride. Clean and lubricate the chain after wet weather. Replace worn brake pads and inspect wheel spokes for damage.'),
 ('bread', 'Baking sourdough bread', 'Mix flour and water with an active starter. Allow bulk fermentation before shaping the loaf. Steam during the first part of baking helps the crust expand and develop a crisp surface.'),
 ('camera', 'Photographing moving subjects', 'A fast shutter speed freezes motion while a slower shutter shows movement. Increase light or sensor sensitivity when a short exposure would otherwise be too dark. Continuous autofocus helps track a moving subject.'),
 ('music', 'Learning piano scales', 'Practice slowly with even timing before increasing tempo. Use consistent fingering and keep the hands relaxed. Short daily sessions help build coordination better than occasional exhausting practice.'),
 ('hiking', 'Planning a mountain hike', 'Check the weather and trail conditions before departure. Carry water, layers and a map. Tell someone your intended route and expected return time, and turn around early if conditions deteriorate.'),
 ('coffee', 'Brewing filter coffee', 'Grind coffee just before brewing and use clean hot water. Adjust grind size to control extraction. A consistent ratio of water to coffee makes taste comparisons more useful.'),
 ('astronomy', 'Observing the night sky', 'Dark locations away from city lights reveal faint stars. Let your eyes adapt before observing. A star chart helps identify constellations and locate bright planets near the ecliptic.'),
]
documents=[]; queries=[]
for topic, title1, text1, title2, text2, query in TOPICS:
 for i,(title,text) in enumerate(((title1,text1),(title2,text2)),1):
  documents.append({'id':f'{topic}-{i}','title':title,'text':text})
 queries.append({'text':query,'relevant':[f'{topic}-1',f'{topic}-2']})
for id,title,text in DISTRACTORS:documents.append({'id':id,'title':title,'text':text})
Path(__file__).with_name('evaluation.json').write_text(json.dumps({'description':'Original English corpus: 32 documents, 12 manually labelled queries; illustrative, not an external benchmark.', 'documents':documents,'queries':queries},indent=2)+'\n')
